<script setup lang="ts">
import { nextTick, onMounted, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { post } from '../../utils/request'
const sessionId = ref(''); const input = ref(''); const messages = ref<Array<{ role: string; text: string }>>([]); const loading = ref(false); const box = ref<HTMLElement>()
async function createSession() { try { sessionId.value = await post<string>('/admin/chat/session'); messages.value = [{ role: 'assistant', text: '你好，我可以查询档口、菜品和订单，也可以协助处理受控写操作。' }] } catch (e) { ElMessage.error((e as Error).message) } }
async function send() { const text = input.value.trim(); if (!text || loading.value) return; input.value = ''; messages.value.push({ role: 'user', text }); loading.value = true; try { const token = localStorage.getItem('token') || ''; const response = await fetch(`/api/admin/chat?memoryId=${encodeURIComponent(sessionId.value)}&memory=${encodeURIComponent(text)}`, { headers: { token } }); if (!response.ok || !response.body) throw new Error('AI 服务暂不可用'); const reader = response.body.getReader(); const decoder = new TextDecoder(); let answer = ''; messages.value.push({ role: 'assistant', text: '' }); const current = messages.value[messages.value.length - 1]; while (true) { const { done, value } = await reader.read(); if (done) break; answer += decoder.decode(value, { stream: true }); current.text = answer; await nextTick(); box.value?.scrollTo({ top: box.value.scrollHeight }); } } catch (e) { ElMessage.error((e as Error).message); messages.value.push({ role: 'assistant', text: '这次请求没有完成，请检查 AI 配置或稍后重试。' }) } finally { loading.value = false } }
onMounted(createSession)
</script>
<template><div class="page-card ai-page"><div class="page-header"><div><h2 class="page-title">运营 AI 助手</h2><p class="page-subtitle">通过工具调用查询真实业务数据，写操作必须二次确认。</p></div></div><div class="page-actionbar"><div class="query-area"><span class="muted">当前会话：{{ sessionId ? sessionId.slice(0, 12) + "..." : "未创建" }}</span></div><div class="action-area"><el-button @click="createSession">新建会话</el-button></div></div><div ref="box" class="chat-box"><div v-for="(message, index) in messages" :key="index" :class="['bubble', message.role]">{{ message.text }}</div><div v-if="loading" class="bubble assistant">正在整理业务数据…</div></div><div class="chat-input"><el-input v-model="input" type="textarea" :rows="2" placeholder="例如：帮我查一下今天待接单的订单" @keyup.ctrl.enter="send" /><el-button type="primary" :loading="loading" @click="send">发送</el-button></div><p class="muted">快捷键：Ctrl + Enter 发送</p></div></template>
<style scoped>.ai-page{display:flex;flex-direction:column;min-height:calc(100vh - 108px)}.chat-box{flex:1;min-height:360px;max-height:58vh;overflow:auto;padding:10px;background:#f6faf8;border-radius:12px}.bubble{max-width:78%;padding:12px 15px;border-radius:13px;margin:8px 0;line-height:1.65;white-space:pre-wrap}.bubble.assistant{background:#fff;border:1px solid #e2ece7;color:#334b46}.bubble.user{background:#0f766e;color:#fff;margin-left:auto}.chat-input{display:flex;gap:10px;margin-top:14px;align-items:flex-end}.chat-input .el-input{flex:1}</style>
